                const storedRows = Number(row.stored_row_count || row.storedRowCount || 0);
                if (['policy_disabled', 'strategy_disabled', 'disabled'].includes(raw)) return 'policy_disabled';
                if (['stale_running', 'task_stale_running'].includes(raw) || etl === 'stale_running') return 'stale_running';
                if (['running', 'collecting', 'syncing'].includes(raw)) return 'collecting';
                if (['failed', 'capture_failed', 'not_stored'].includes(raw) || ['capture_failed', 'not_stored', 'capture_success_not_stored'].includes(etl)) return 'failed';
                if (['stale', 'expired'].includes(raw) || row.freshness === 'stale') return 'stale';
