            const filterUserStatus = ref('');
            const filterUserHotelId = ref('');
            const userLastLoginSortDirection = ref('desc');
            const compassHotelOptions = computed(() => permittedHotels.value.length ? permittedHotels.value : hotels.value);
            const dualOtaHotelOrderStorageKey = () => `suxios_dual_ota_hotel_order_${user.value?.id || 'guest'}_v1`;
            const normalizeDualOtaHotelOrderIds = (orderIds = [], options = []) => {
                const availableIds = (Array.isArray(options) ? options : [])
                    .map(hotel => String(hotel?.id || '').trim())
                    .filter(Boolean);
                const availableSet = new Set(availableIds);
                const seen = new Set();
                const orderedIds = [];
                (Array.isArray(orderIds) ? orderIds : []).forEach((hotelId) => {
                    const key = String(hotelId || '').trim();
                    if (!key || !availableSet.has(key) || seen.has(key)) return;
                    seen.add(key);
                    orderedIds.push(key);
                });
                availableIds.forEach((hotelId) => {
                    if (seen.has(hotelId)) return;
                    seen.add(hotelId);
                    orderedIds.push(hotelId);
                });
                return orderedIds;
            };
            const readDualOtaHotelOrderIds = () => {
                try {
                    const parsed = JSON.parse(localStorage.getItem(dualOtaHotelOrderStorageKey()) || '[]');
                    if (!Array.isArray(parsed)) return [];
                    return [...new Set(parsed
                        .map(hotelId => String(hotelId || '').trim())
                        .filter(Boolean))].slice(0, 500);
                } catch (error) {
                    return [];
                }
            };
            const dualOtaHotelOrderIds = ref(readDualOtaHotelOrderIds());
            const dualOtaHotelOrderDraftIds = ref([]);
            const showDualOtaHotelOrderModal = ref(false);
            const dualOtaHasCustomHotelOrder = computed(() => dualOtaHotelOrderIds.value.length > 0);
            const dualOtaHotelOrderModeText = computed(() => dualOtaHasCustomHotelOrder.value ? '我的排序' : '常用优先');
            const dualOtaHotelSearchCountStorageKey = () => `suxios_dual_ota_hotel_search_counts_${user.value?.id || 'guest'}_v1`;
            const readDualOtaHotelSearchCounts = () => {
                try {
                    const parsed = JSON.parse(localStorage.getItem(dualOtaHotelSearchCountStorageKey()) || '{}');
                    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
                    return Object.fromEntries(Object.entries(parsed)
                        .map(([hotelId, count]) => [String(hotelId), Number(count)])
                        .filter(([hotelId, count]) => hotelId && Number.isFinite(count) && count > 0));
                } catch (error) {
                    return {};
                }
            };
            const dualOtaHotelSearchCounts = ref(readDualOtaHotelSearchCounts());
            let dualOtaSuppressHotelSearchRecord = false;
            const saveDualOtaHotelSearchCounts = () => {
                try {
                    localStorage.setItem(dualOtaHotelSearchCountStorageKey(), JSON.stringify(dualOtaHotelSearchCounts.value || {}));
                } catch (error) {
                    console.warn('保存今日经营看板门店使用记录失败:', error);
                }
            };
            const recordDualOtaHotelSearch = (hotelId) => {
                const key = String(hotelId || '').trim();
                if (!key) return;
                const current = Number(dualOtaHotelSearchCounts.value?.[key] || 0);
                dualOtaHotelSearchCounts.value = {
                    ...(dualOtaHotelSearchCounts.value || {}),
                    [key]: Math.min(current + 1, 9999),
                };
                saveDualOtaHotelSearchCounts();
            };
            const dualOtaCurrentHotelOptions = computed(() => {
                const options = Array.isArray(compassHotelOptions.value) ? compassHotelOptions.value : [];
                if (dualOtaHasCustomHotelOrder.value) {
                    const orderIds = normalizeDualOtaHotelOrderIds(dualOtaHotelOrderIds.value, options);
                    const optionById = new Map(options.map(hotel => [String(hotel?.id || '').trim(), hotel]));
                    return orderIds.map(hotelId => optionById.get(hotelId)).filter(Boolean);
                }
                const counts = dualOtaHotelSearchCounts.value || {};
                return options
                    .map((hotel, index) => ({
                        hotel,
                        index,
                        count: Number(counts[String(hotel?.id || '')] || 0),
                    }))
                    .sort((a, b) => (b.count - a.count) || (a.index - b.index))
                    .map(item => item.hotel);
            });
            const dualOtaHotelOrderRows = computed(() => {
                const options = Array.isArray(compassHotelOptions.value) ? compassHotelOptions.value : [];
                const optionById = new Map(options.map(hotel => [String(hotel?.id || '').trim(), hotel]));
                return normalizeDualOtaHotelOrderIds(dualOtaHotelOrderDraftIds.value, options)
                    .map(hotelId => optionById.get(hotelId))
                    .filter(Boolean);
            });
            const openDualOtaHotelOrder = () => {
                if (!dualOtaCurrentHotelOptions.value.length) {
                    showToast('当前账号暂无可排序门店', 'warning');
                    return;
                }
                dualOtaHotelOrderDraftIds.value = dualOtaCurrentHotelOptions.value
                    .map(hotel => String(hotel?.id || '').trim())
                    .filter(Boolean);
                showDualOtaHotelOrderModal.value = true;
            };
            const closeDualOtaHotelOrder = () => {
                showDualOtaHotelOrderModal.value = false;
                dualOtaHotelOrderDraftIds.value = [];
            };
            const moveDualOtaHotelOrder = (hotelId, direction) => {
                const options = Array.isArray(compassHotelOptions.value) ? compassHotelOptions.value : [];
                const orderIds = normalizeDualOtaHotelOrderIds(dualOtaHotelOrderDraftIds.value, options);
                const key = String(hotelId || '').trim();
                const currentIndex = orderIds.indexOf(key);
                const nextIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;
                if (currentIndex < 0 || nextIndex < 0 || nextIndex >= orderIds.length) return;
                [orderIds[currentIndex], orderIds[nextIndex]] = [orderIds[nextIndex], orderIds[currentIndex]];
                dualOtaHotelOrderDraftIds.value = orderIds;
            };
            const moveDualOtaHotelOrderToTop = (hotelId) => {
                const options = Array.isArray(compassHotelOptions.value) ? compassHotelOptions.value : [];
                const orderIds = normalizeDualOtaHotelOrderIds(dualOtaHotelOrderDraftIds.value, options);
                const key = String(hotelId || '').trim();
                const currentIndex = orderIds.indexOf(key);
                if (currentIndex <= 0) return;
                orderIds.splice(currentIndex, 1);
                orderIds.unshift(key);
                dualOtaHotelOrderDraftIds.value = orderIds;
            };
            const saveDualOtaHotelOrder = () => {
                const options = Array.isArray(compassHotelOptions.value) ? compassHotelOptions.value : [];
                const normalizedOrder = normalizeDualOtaHotelOrderIds(dualOtaHotelOrderDraftIds.value, options);
                if (!normalizedOrder.length) {
                    showToast('当前账号暂无可保存门店', 'warning');
                    return;
                }
                try {
                    localStorage.setItem(dualOtaHotelOrderStorageKey(), JSON.stringify(normalizedOrder));
                } catch (error) {
                    console.warn('保存当前账号门店顺序失败:', error);
                    showToast('门店顺序保存失败，请检查浏览器存储权限', 'error');
                    return;
                }
                dualOtaHotelOrderIds.value = normalizedOrder;
                closeDualOtaHotelOrder();
                showToast('已保存我的门店顺序');
            };
            const resetDualOtaHotelOrder = () => {
                try {
                    localStorage.removeItem(dualOtaHotelOrderStorageKey());
                } catch (error) {
                    console.warn('恢复常用优先门店顺序失败:', error);
                    showToast('恢复默认顺序失败，请检查浏览器存储权限', 'error');
                    return;
                }
                dualOtaHotelOrderIds.value = [];
                closeDualOtaHotelOrder();
                showToast('已恢复常用优先排序');
            };
            const reportHotelOptionExists = (hotelId) => {
                const key = String(hotelId || '').trim();
                if (!key) return false;
                return [
                    ...(Array.isArray(permittedHotels.value) ? permittedHotels.value : []),
                    ...(Array.isArray(hotels.value) ? hotels.value : []),
                ].some(hotel => String(hotel?.id || '').trim() === key);
            };
            const resolveDefaultReportHotelId = () => {
                const boundHotelId = String(user.value?.hotel_id || '').trim();
                if (boundHotelId && reportHotelOptionExists(boundHotelId)) return boundHotelId;
                return '';
            };
            let suppressNextReportHotelDashboardRefresh = false;
            let defaultReportHotelMissingNoticeUserId = '';
            const notifyMissingDefaultReportHotel = () => {
                const userId = String(user.value?.id || '').trim();
                if (!userId
                    || !hotelListSnapshotReady.value
                    || defaultReportHotelMissingNoticeUserId === userId) {
                    return;
                }
                defaultReportHotelMissingNoticeUserId = userId;
                showToast('尚未设置可用主门店，普通板块将保持未选择；请前往门店管理设置主门店。', 'warning');
            };
            const applyDefaultReportHotel = (options = {}) => {
                const currentHotelId = String(filterReportHotel.value || '').trim();
                const mainHotelId = resolveDefaultReportHotelId();
                if (!mainHotelId) {
                    if (user.value?.id && hotelListSnapshotReady.value) {
                        notifyMissingDefaultReportHotel();
                    }
                    if (!currentHotelId) return;
                    if (options.suppressDashboardRefresh === true) {
                        suppressNextReportHotelDashboardRefresh = true;
                    }
                    dualOtaSuppressHotelSearchRecord = true;
                    filterReportHotel.value = '';
                    nextTick(() => {
                        dualOtaSuppressHotelSearchRecord = false;
                    });
                    return;
                }
                defaultReportHotelMissingNoticeUserId = '';
                if (currentHotelId && reportHotelOptionExists(currentHotelId)) return;
                const storedPreferences = readDualOtaWorkbenchPreferences();
                const hasStoredHotelId = Object.prototype.hasOwnProperty.call(storedPreferences, 'hotel_id');
                const storedHotelId = hasStoredHotelId ? String(storedPreferences.hotel_id || '').trim() : '';
                const availableOptions = Array.isArray(compassHotelOptions.value) ? compassHotelOptions.value : [];
                let defaultHotelId = mainHotelId;
                if (hasStoredHotelId) {
                    if (!storedHotelId) {
                        defaultHotelId = '';
                    } else if (reportHotelOptionExists(storedHotelId)) {
                        defaultHotelId = storedHotelId;
                    } else if (!availableOptions.length) {
                        return;
                    }
                }
                if (currentHotelId === defaultHotelId) return;
                if (options.suppressDashboardRefresh === true) {
                    suppressNextReportHotelDashboardRefresh = true;
                }
                dualOtaSuppressHotelSearchRecord = true;
                filterReportHotel.value = defaultHotelId;
                nextTick(() => {
                    dualOtaSuppressHotelSearchRecord = false;
                });
            };
            watch(compassHotelOptions, (options) => {
                dualOtaHasAvailableHotels.value = Array.isArray(options) && options.length > 0;
                applyDefaultReportHotel();
            }, { immediate: true });
            const knowledgeCenterHotelOptions = computed(() => {
                const pool = permittedHotels.value.length ? permittedHotels.value : hotels.value;
                return (Array.isArray(pool) ? pool : []).filter(item => item && item.id);
            });
            const defaultKnowledgeCenterHotelId = () => {
                const options = knowledgeCenterHotelOptions.value;
                const selected = String(knowledgeCenterTargetHotelId.value || '').trim();
                if (selected && options.some(item => String(item.id) === selected)) {
                    return selected;
                }
                return options.length === 1 ? String(options[0].id) : '';
            };
            const knowledgeCenterBaseSourceOptions = requireSystemStatic('knowledgeCenterBaseSourceOptions');
            const knowledgePromotionSourceCandidates = computed(() => {
                const hotelId = Number(knowledgePromotionHotelId.value || 0);
                return (Array.isArray(knowledgePromotionSourceVersions.value) ? knowledgePromotionSourceVersions.value : [])
                    .filter((version) => Number(version?.hotel_id || 0) === hotelId
                        && String(version?.validation_status || '') === 'candidate'
                        && String(version?.lifecycle_status || '') === 'active');
            });
            const knowledgePromotionEligibleMemories = computed(() => {
                const hotelId = Number(knowledgePromotionHotelId.value || 0);
                const revision = knowledgePromotionSelectedCandidate.value?.current_revision || {};
                const expectedPlatform = String(revision?.applicability?.platform || '').trim().toLowerCase();
                const expectedScope = String(revision?.scope?.source_scope || '').trim().toLowerCase();
                return (Array.isArray(knowledgePromotionMemories.value) ? knowledgePromotionMemories.value : [])
                    .filter((memory) => {
                        const context = memory && typeof memory.context === 'object' && memory.context ? memory.context : {};
                        if (Number(memory?.hotel_id || 0) !== hotelId
                            || String(memory?.memory_layer || '') !== 'execution_review'
                            || String(memory?.quality_status || '') !== 'verified'
                            || String(memory?.usage_level || '') !== 'decision_support'
                            || String(memory?.lifecycle_status || '') !== 'active'
                            || context.outcome_verified !== true
                            || context.positive_outcome_verified !== true
                            || context.sop_candidate_ready !== true
                        ) return false;
                        if (expectedPlatform && String(memory?.platform || '').trim().toLowerCase() !== expectedPlatform) return false;
                        if (expectedScope && String(memory?.source_scope || '').trim().toLowerCase() !== expectedScope) return false;
                        return true;
                    });
            });
            const knowledgePromotionApprovalGate = computed(() => {
                const eligibleById = new Map(knowledgePromotionEligibleMemories.value.map((memory) => [Number(memory.id), memory]));
                const selected = Array.from(new Set((knowledgePromotionForm.value.evidence_memory_ids || [])
                    .map((id) => Number(id || 0))
                    .filter((id) => id > 0 && eligibleById.has(id))))
                    .map((id) => eligibleById.get(id));
                const taskIds = new Set(selected.map((memory) => Number(memory.source_record_id || 0)).filter((id) => id > 0));
                const businessDates = new Set(selected
                    .map((memory) => String(memory.business_date || '').trim())
                    .filter((date) => /^\d{4}-\d{2}-\d{2}$/.test(date)));
                const gaps = [];
                if (selected.length < 3) gaps.push(`还需选择 ${3 - selected.length} 条合格记忆`);
                if (taskIds.size < 3) gaps.push(`独立任务 ${taskIds.size}/3`);
                if (businessDates.size < 2) gaps.push(`经营日期 ${businessDates.size}/2`);
                return {
                    ready: selected.length >= 3 && taskIds.size >= 3 && businessDates.size >= 2,
                    selected_ids: selected.map((memory) => Number(memory.id)),
                    memory_count: selected.length,
                    task_count: taskIds.size,
                    business_date_count: businessDates.size,
                    gaps,
                };
            });
            const knowledgePromotionStats = computed(() => ({
                source_candidates: knowledgePromotionSourceCandidates.value.length,
                promotion_candidates: knowledgePromotionCandidates.value.length,
                eligible_memories: knowledgePromotionEligibleMemories.value.length,
            }));
            const knowledgeImportModeMetaMap = requireSystemStatic('knowledgeImportModeMetaMap');
            const buildKnowledgeImportRequestBody = requireSystemStatic('buildKnowledgeImportRequestBody');
            const knowledgeImportSuccessMessage = requireSystemStatic('knowledgeImportSuccessMessage');
            const knowledgeImportErrorMessage = requireSystemStatic('knowledgeImportErrorMessage');
            const knowledgeImportModeMeta = (mode) => knowledgeImportModeMetaMap[mode] || { label: '导入内容', placeholder: '每段内容用空行分隔' };
            const knowledgeImportCurrentMeta = computed(() => knowledgeImportModeMeta(knowledgeCenterImportForm.value.mode));
            const knowledgeCenterStats = computed(() => {
                const stats = knowledgeCenterUnits.value.reduce((result, unit) => {
                    const status = unit.status || 'pending';
                    const source = String(unit.source || '').trim();
                    if (status === 'done') result.done += 1;
                    if (status === 'pending') result.pending += 1;
                    if (status === 'error') result.error += 1;
                    if (source) result.sourceSet.add(source);
                    result.chunks += Number(unit.chunk_count || 0);
                    return result;
                }, { done: 0, pending: 0, error: 0, chunks: 0, sourceSet: new Set() });
                const unitCount = Math.max(knowledgeCenterUnits.value.length, 1);
                return {
                    done: stats.done,
                    pending: stats.pending,
                    error: stats.error,
                    chunks: stats.chunks,
                    sources: stats.sourceSet.size,
                    avg_chunks: (stats.chunks / unitCount).toFixed(1),
                };
            });
            const formatKnowledgeDistillationMetric = (value) => {
                if (value === undefined || value === null || value === '') return '-';
                const numberValue = Number(value);
                if (!Number.isFinite(numberValue)) return String(value);
                if (Math.abs(numberValue) > 0 && Math.abs(numberValue) < 0.0001) return numberValue.toExponential(2);
                return numberValue.toFixed(4).replace(/\.?0+$/, '');
            };
            const knowledgeDistillationMetricRows = computed(() => {
                const result = knowledgeDistillationResult.value || {};
                const metrics = result.metrics || {};
                return [
                    { label: '模式', value: result.label || result.mode || '-' },
                    { label: '批次', value: metrics.batches ?? result.max_batches ?? '-' },
                    { label: 'CE Loss', value: formatKnowledgeDistillationMetric(metrics.ce_loss) },
                    { label: 'KD Loss', value: formatKnowledgeDistillationMetric(metrics.kd_loss) },
                ];
            });
            const knowledgeCenterSourceOptions = computed(() => {
                const sources = new Set(knowledgeCenterBaseSourceOptions);
                knowledgeCenterUnits.value.forEach(unit => {
                    const source = String(unit.source || '').trim();
                    if (source) sources.add(source);
                });
                if (knowledgeCenterFilter.value.source) {
                    sources.add(knowledgeCenterFilter.value.source);
                }
                return Array.from(sources);
            });
            const knowledgeCenterIsFiltered = computed(() => {
                return !!(
                    knowledgeCenterFilter.value.keyword ||
                    knowledgeCenterFilter.value.status ||
                    knowledgeCenterFilter.value.tag ||
                    knowledgeCenterFilter.value.source ||
                    knowledgeCenterFilter.value.module ||
                    knowledgeCenterFilter.value.role ||
                    knowledgeCenterFilter.value.scene ||
                    knowledgeCenterFilter.value.platform ||
                    knowledgeCenterFilter.value.evidence_level ||
                    knowledgeCenterFilter.value.version
                );
            });

            // 模态框
            const showHotelModal = ref(false);
            const showHotelDeleteModal = ref(false);
            const hotelDeleteTarget = ref(null);
            const hotelDeleteLoading = ref(false);
            const hotelDeleteError = ref('');
            const hotelDeleteReferences = ref([]);
            const hotelDeleteCanForce = ref(false);
            const hotelDeletePreviewReady = ref(false);
            const hotelDeleteConfirmationName = ref('');
            const showHotelMergeModal = ref(false);
            const hotelMergeForm = ref(createHotelMergeForm());
            const hotelMergePreview = ref(null);
            const hotelMergeConfirmationInput = ref(null);
