            const operationDisplayFormatters = { value: operationValue, money: operationMoney };
            const operationSummaryCards = computed(() => buildOperationSummaryCards(operationFullData.value?.summary || {}, operationDisplayFormatters));
            const operationOtaCards = computed(() => buildOperationOtaCards(operationFullData.value?.ota || {}, operationDisplayFormatters));
            const operationCompetitorCards = computed(() => buildOperationCompetitorCards(operationFullData.value?.competitors || {}, operationDisplayFormatters));
            const operationSourceBrief = computed(() => buildOperationSourceBrief(operationFullData.value));
